export function playerHtml(id='qa',fields={sensitivity:'1.25',dpi:'800',zoom_sensitivity_ratio_mouse:'1',cl_crosshair_length:'3',cl_crosshair_gap:'2',cl_crosshair_thickness:'2',cl_crosshairstyle:'Static Cross',cl_crosshaircolor_r:'11',cl_crosshaircolor_g:'255',cl_crosshaircolor_b:'0',viewmodel_fov:'65',resolution:'1280x960',display_mode:'Fullscreen',max_fps:'600',shader_detail:'Low',wait_for_vertical_sync:'Disabled',hud_scaling:'1',cl_radar_scale:'.7'}){
  return `<link rel="canonical" href="https://prosettings.net/players/${id}/"><h1>${id==='qa'?'Jogador QA':id}</h1><time datetime="2026-10-15T12:00:00Z">Oct 15</time><table><tr class="field-team"><td>Time QA</td></tr></table><section class="avatar"><img src="https://prosettings.net/wp-content/uploads/qa-player.png"></section><div id="cs2-settings"><table>${Object.entries(fields).map(([key,value])=>`<tr data-field="${key}"><th>${key}</th><td>${value}</td></tr>`).join('')}</table><section id="cs2_config"></section></div><p>Comment says sensitivity 20</p>`;
}
export function catalogHtml(){return '<table id="pro-list-table"><thead><tr><th></th><th>Team</th><th>Player</th><th>Role</th><th>DPI</th><th>Sens</th><th>Resolution</th></tr></thead><tbody><tr><td></td><td>Time QA</td><td><a href="https://prosettings.net/players/qa/">Jogador QA</a></td><td>Rifler</td><td>800</td><td>1.25</td><td>1280x960</td></tr></tbody></table>';}
export function teamsHtml(){return '<section><div class="js-team-card" data-games="468" data-name="Time QA"><a href="https://prosettings.net/teams/time-qa/">Time QA</a><img src="https://prosettings.net/wp-content/uploads/qa-team.png"></div></section>';}
